script:
(function () {
  'use strict';
  // Retirement shortfall. Saving phase (monthly): i = (1 + return before)^(1/12) - 1, m = 12 x years
  // until retirement, contributions C at the end of each month:
  //   projected P = S x (1 + i)^m + C x ((1 + i)^m - 1) / i      (C x m when i = 0)
  // Need at retirement: first-year withdrawal W = (spending - other income) x (1 + inflation)^years
  // / (1 - tax rate), taken at the start of each retirement year, rising g = inflation a year (0 if
  // unticked), discounted at the return during retirement r:  needed N = sum over j < R of
  // W x ((1 + g) / (1 + r))^j. Shortfall = N - P. Extra monthly saving = shortfall / FV factor
  // ((1 + i)^m - 1) / i; lump sum today = shortfall / (1 + i)^m.
  // CHECKS (Node, scratch tests): $150,000 + $600/month at 6% for 20 years = $481,070.32 +
  // $272,063.18 (closed-form values); with 0% returns and inflation, $36,000 a year for 30
  // years needs $1,080,000 at 0% tax; the needed amount matches the growing-annuity-due closed form
  // W x (1 - ((1 + g)/(1 + r))^R) / (1 - (1 + g)/(1 + r)); adding the extra monthly saving to the
  // month-by-month run ends exactly at the needed amount; years to retirement 0 gives no NaN.
  var MAX_YEARS = 100;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var one = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function monthlyRate(r) { return Math.pow(1 + r, 1 / 12) - 1; }
  // Future value of $1 a month, paid at the end of each month, after m months.
  function fvFactor(i, m) { return i === 0 ? m : (Math.pow(1 + i, m) - 1) / i; }

  // Year-end balances while saving S now plus C a month for n years.
  function path(S, C, i, n) {
    var bal = S, rows = [];
    for (var y = 1; y <= n; y++) {
      for (var k = 0; k < 12; k++) bal = bal * (1 + i) + C;
      rows.push(bal);
    }
    return rows;
  }

  // Years a balance lasts with start-of-year withdrawals W rising g a year at return r.
  function lasts(B, W, r, g) {
    if (W <= 0) return null;
    var bal = B;
    for (var y = 0; y < MAX_YEARS; y++) {
      var w = W * Math.pow(1 + g, y);
      if (w > bal + 1e-9) return y + bal / w;
      bal = (bal - w) * (1 + r);
    }
    return null;
  }

  function update() {
    var n = num('rsYearsTo'), R = num('rsYearsIn'), S = num('rsSavings'), C = num('rsMonthly'),
        spend = num('rsExpenses'), other = num('rsOther'), pre = num('rsPreRate'), post = num('rsPostRate'),
        inf = num('rsInflation'), tax = num('rsTax'), indexed = document.getElementById('rsIndex').checked;
    var error = document.getElementById('rsError');
    var bad = [n, R, S, C, spend, other, pre, post, inf, tax].some(isNaN) || n < 0 || n > 60 || n !== Math.floor(n) ||
              R < 1 || R > 60 || R !== Math.floor(R) || S < 0 || C < 0 || spend < 0 || other < 0 ||
              pre < 0 || pre > 30 || post < 0 || post > 30 || inf < 0 || inf > 20 || tax < 0 || tax > 60;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, whole years (0 to 60 before retirement, 1 to 60 in retirement), returns up to 30%, inflation up to 20% and a tax rate up to 60%.';
      return;
    }
    var i = monthlyRate(pre / 100), m = n * 12, r = post / 100, f = inf / 100, g = indexed ? f : 0;
    var growth = Math.pow(1 + i, m), factor = fvFactor(i, m);
    var projected = S * growth + C * factor;
    var W = Math.max(0, spend - other) * Math.pow(1 + f, n) / (1 - tax / 100);
    var needed = 0;
    for (var j = 0; j < R; j++) needed += W * Math.pow((1 + g) / (1 + r), j);
    var gap = needed - projected;
    var extra = gap > 0 && m > 0 ? gap / factor : 0;
    var lump = gap > 0 ? gap / growth : 0;

    set('rsGapLabel', gap > 0 ? 'Shortfall' : 'Surplus');
    set('rsGap', money.format(Math.abs(gap)));
    set('rsProjected', money.format(projected));
    set('rsNeeded', money.format(needed));
    set('rsFirstNeed', money.format(W));
    if (gap <= 0) {
      set('rsExtra', '$0 a month');
      set('rsTotalMonthly', money.format(C) + ' a month');
      set('rsLump', '$0');
    } else if (m === 0) {
      set('rsExtra', 'Not possible');
      set('rsTotalMonthly', 'Not possible with 0 years left');
      set('rsLump', money.format(lump));
    } else {
      set('rsExtra', money.format(extra) + ' a month');
      set('rsTotalMonthly', money.format(C + extra) + ' a month');
      set('rsLump', money.format(lump));
    }
    var yl = lasts(projected, W, r, g);
    set('rsLasts', W <= 0 ? 'No withdrawals needed' : yl === null ? MAX_YEARS + '+ years' : one.format(yl) + ' years');
    var summary;
    if (W <= 0) summary = 'Your other income covers your planned spending, so you would not need to draw on your savings.';
    else if (gap > 0) summary = 'You are on track for ' + money.format(projected) + ' but need about ' + money.format(needed) +
      ' to cover ' + R + ' years of withdrawals. ' + (m > 0 ? 'Saving an extra ' + money.format(extra) + ' a month from now on would close the gap.'
      : 'With no years left to save, you would need to invest ' + money.format(lump) + ' more now, spend less, or work longer.');
    else summary = 'You are on track for ' + money.format(projected) + ', which is ' + money.format(-gap) +
      ' more than the ' + money.format(needed) + ' you need for ' + R + ' years of withdrawals.';
    set('rsSummary', summary);

    var cur = path(S, C, i, n), plus = path(S, C + extra, i, n), rows = ['<tr><td>Today</td><td>' + money.format(S) +
      '</td><td>' + money.format(S) + '</td></tr>'];
    for (var y = 0; y < n; y++) {
      rows.push('<tr><td>' + (y + 1) + '</td><td>' + money.format(cur[y]) + '</td><td>' + money.format(plus[y]) + '</td></tr>');
    }
    document.getElementById('rsSchedule').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
